package com.studentgig.ai;
import com.fasterxml.jackson.databind.*; import com.studentgig.model.User; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*;
@Service public class AIResumeService {private final RestClient client=RestClient.builder().build();private final ObjectMapper mapper=new ObjectMapper();
 public String generate(User u,String role,String jd){String key=System.getenv("AI_API_KEY");if(key==null||key.isBlank())return fallback(u,role);try{String prompt="Create an ATS-friendly resume as clean HTML only. Target role: "+role+". Job description: "+jd+". Candidate data: name="+u.name+", degree="+u.degree+", graduation="+u.graduationYear+", skills="+u.skills+", experience="+u.experience+", bio="+u.bio+", links="+u.github+" "+u.linkedin+" "+u.portfolio+". Do not invent employers, degrees, dates or metrics. Use concise bullets.";Map<String,Object> body=Map.of("model",System.getenv().getOrDefault("AI_MODEL","gpt-4o-mini"),"messages",List.of(Map.of("role","system","content","You are a professional resume writer."),Map.of("role","user","content",prompt)),"temperature",0.3);Map<?,?> out=client.post().uri("https://api.openai.com/v1/chat/completions").header(HttpHeaders.AUTHORIZATION,"Bearer "+key).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);List<?> choices=(List<?>)out.get("choices");Map<?,?> first=(Map<?,?>)choices.get(0);Map<?,?> msg=(Map<?,?>)first.get("message");return String.valueOf(msg.get("content")).replace("```html","").replace("```","");}catch(Exception e){return fallback(u,role);}}
 private String fallback(User u,String role){String skills=esc(u.skills==null||u.skills.isBlank()?"Java, SQL, Problem Solving":u.skills);String summary=esc(u.bio==null||u.bio.isBlank()?"Motivated student targeting a "+role+" role, with a strong foundation in technology and a practical, learning-focused approach.":u.bio);String exp=esc(u.experience==null||u.experience.isBlank()?"Academic projects, coursework and hands-on practice. Add internships and measurable achievements to strengthen this section.":u.experience);return "<article class='resume-paper professional-resume'><div class='resume-name'>"+esc(u.name)+"</div><div class='resume-role'>"+esc(role)+"</div><div class='resume-contact'>"+esc(u.email)+(u.phone==null||u.phone.isBlank()?"":" · "+esc(u.phone))+(u.location==null||u.location.isBlank()?"":" · "+esc(u.location))+"<br>"+String.join(" · ",Arrays.asList(u.linkedin,u.github,u.portfolio).stream().filter(Objects::nonNull).filter(x->!x.isBlank()).map(this::esc).toList())+"</div><h3>PROFILE</h3><p>"+summary+"</p><h3>SKILLS</h3><p>"+skills+"</p><h3>EXPERIENCE</h3><p>"+exp+"</p><h3>EDUCATION</h3><p><b>"+esc(u.degree==null?"Degree":u.degree)+"</b> "+(u.graduationYear==null?"":"| "+esc(u.graduationYear.toString()))+"</p><h3>ACHIEVEMENTS & CERTIFICATIONS</h3><p>Add certifications, hackathons, awards, coding profiles and project outcomes from your profile.</p></article>";}
 private String esc(String s){return String.valueOf(s==null?"":s).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}}
